-- Phase 5 (SPEC §18, §20, §21): canonical MIS heads and global library seed (generated from
-- packages/semantic), head classes, and semantic / engine / validation config.

-- The class a mapping must not cross (gross-profit boundary, statement side). ADR 0020.
alter table public.mis_heads add column class text not null default 'memo'
  check (class in ('income', 'direct_cost', 'indirect_cost', 'equity_liability', 'asset', 'memo'));

-- BEGIN GENERATED SEED (packages/semantic seed-sql)
update public.mis_heads set class = 'memo', version = 1 where code = 'UNMAPPED';
-- END GENERATED SEED

  -- SPEC §18 step 4: fuzzy library matches at or above this Dice similarity are proposed for review.
  ('semantic.fuzzy_threshold', '"0.85"'::jsonb),
  -- SPEC §18: a library candidate needs this many distinct accounts (admin-reviewed, Phase 9).
  ('semantic.library_promotion_min_accounts', '5'::jsonb),
  -- SPEC §21 V3: trial balance debit/credit tolerance in paise.
  ('validation.tb_tolerance_paise', '0'::jsonb),
  -- SPEC §21 V5/V6: balance sheet and profit reconciliation tolerance in paise.
  ('validation.reconciliation_tolerance_paise', '0'::jsonb),
  -- SPEC §20: ageing buckets in days from bill date; the last bucket is open-ended.
  ('engine.ageing_buckets', '[[0, 30], [31, 60], [61, 90], [91, 180], [181, null]]'::jsonb),
  -- SPEC §21 V10: heads whose balance direction is checked, with the expected sign.
  ('validation.sign_sanity_heads', '["REV", "COGS", "EMP", "OPEX", "DA", "FIN", "CA_CASH", "CA_INVENTORY", "CL_PAYABLES", "CA_RECEIVABLES"]'::jsonb)
on conflict (key, version) do nothing;
